"""Original scripts/storyboards for the nine remaining existing Space lessons.
Internal descriptor metadata is never drawn. Each scene specifies its actual model.
"""
import copy

def scene(role,title,speech,board,model):
 return dict(role=role,chapter=title,text=speech,board=[board] if isinstance(board,str) and board else board or [],model=copy.deepcopy(model))
NET=dict(kind='net',cells=[[1,0],[0,1],[1,1],[2,1],[1,2],[1,3]])
BAD=dict(kind='net',cells=[[0,0],[1,0],[2,0],[0,1],[1,1],[2,1]],invalid=True)
GRID=dict(kind='grid',points=[[2,3]],labels=['A'])
DATA=[
(2,'Explore Nets','Connect a flat net to the faces of a solid.',['I can match faces and edges.','I can predict and test a fold.','I can explain a gap or overlap.'],NET,[
('opening','A parcel in a flat envelope','A toy maker wants to post a small box without filling an envelope with air. Could the box travel as a flat shape and become a solid later? Today we will investigate that surprising connection. A good net must do more than contain the correct number of faces.','',NET),
('explanation','Start with a real carton','Find a clean empty carton with an adult, or imagine opening one carefully. Separate its glued tab and unfold the faces without tearing them apart. Put the flat card on the table. The folds show which faces were neighbours before the carton was opened.','Faces stay connected at fold edges.',NET),
('explanation','What makes a net?','A net is a connected flat arrangement of faces that can fold into a solid. The faces must meet along matching whole edges. When folded, they must enclose the object without gaps or overlapping faces. Glue tabs help construction, but tabs are not additional faces.','Connected faces • matching edges • no gaps',NET),
('explanation','Meet our six squares','Our first net has a column of four squares, with an extra square on either side of the second square. All six squares have equal side lengths. Follow each shared edge with your finger. Those joins act like hinges as the card changes from flat to solid.','Six equal square faces',NET),
('question','Will this cross close?','Predict what will happen when the cross folds. Keep the central square still, bring its four neighbours up, and think about the last square. Will that last square cover the opening, or land on a face already occupied? Explain a prediction before we test it.','',NET),
('answer','Worked example one: fold the cube','The central square becomes the base. The squares touching its four sides become four walls. The remaining square continues over the top to close the opening. There are six separate face positions. Each position is filled once, so this cross is a valid cube net.','Base + 4 walls + lid = 6 faces',dict(NET,fold=True)),
('explanation','Track opposite faces','Opposite faces are across the solid from each other. They do not share an edge on the cube. Flat neighbours become neighbours after folding, but two faces far apart on the paper may also meet. Use the folding model instead of deciding from distance on the page alone.','Follow each face through the fold.',dict(NET,fold=True)),
('misconception','Six squares are not enough','A classmate arranges six squares in a two by three rectangle and calls it a cube net. The face count is correct, so that is a sensible first check. But folding creates conflicting face positions. Some faces would overlap, leaving another position empty. Counting cannot replace testing.','A correct count does not prove a net.',BAD),
('explanation','Test systematically','Choose a starting face and label it base. Move from one face to the next across a shared edge. Record where each face would point after folding. If two different faces claim the same position, stop: the arrangement cannot form the intended cube without overlap.','One face in each position',dict(NET,fold=True)),
('explanation','A different solid','A triangular prism needs two matching triangular ends and three rectangular side faces. Use two card triangles and three strips to imagine the construction. Each rectangle must match one side of each triangle, while the other rectangle dimension gives the length of the prism.','2 triangles + 3 rectangles',dict(kind='prismnet')),
('question','Predict the prism faces','Look at the triangular prism net. Imagine the rectangles wrapping around the sides, while the two triangles close the ends. Which faces must have matching shapes? Which edges need to meet? Keep those questions separate from simply asking how many pieces are on the table.','',dict(kind='prismnet')),
('answer','Worked example two: close a prism','The two triangles match exactly and face opposite directions at the ends. The three rectangles form a band around them. Each triangle side meets a rectangle of the same width. Five faces now enclose the prism: two triangles and three rectangles, with no open end.','Matching triangles close both ends.',dict(kind='prismnet',fold=True)),
('explanation','A pyramid net','A square based pyramid has one square base and four triangular faces. A triangle can attach to each side of the square. When the triangles fold inward, their tips meet at the apex. The triangle dimensions must fit that pyramid; arbitrary triangles will not necessarily meet correctly.','1 square + 4 matching triangles',dict(kind='pyramidnet')),
('explanation','Compare prism and pyramid','Both our triangular prism and square based pyramid have five faces, but their nets have different face shapes and connections. The prism has two triangular ends and three rectangles. The pyramid has one square and four triangles. Describe those differences rather than relying on the shared total.','Same face count; different face shapes.',dict(kind='pyramidnet')),
('question','Independent net detective','Imagine a cube net made from only five equal squares. Can folding alone create the missing face? Decide whether the problem is a gap, an overlap, or both. Tell a partner what evidence you would seek before calling any unfamiliar arrangement a valid net.','',dict(kind='net',cells=[[1,0],[0,1],[1,1],[2,1],[1,2]])),
('answer','Explain the missing face','Five squares cannot supply all six cube faces. One face position must remain uncovered. Folding changes the directions of the faces; it does not create another square. A valid construction needs the correct faces, correct dimensions, and a connection pattern that closes without overlap.','Folding cannot create a missing face.',dict(kind='net',cells=[[1,0],[0,1],[1,1],[2,1],[1,2]]))]),
(3,'Design and Test Nets','Design, test and improve a net for packaging.',['I can plan the required faces.','I can check dimensions and joins.','I can explain a useful repair.'],NET,[
('opening','The package that will not close','A designer draws six panels for a gift box, but the lid will not close. Is the problem the number of faces, their dimensions, or their arrangement? We will use evidence to repair a design. A drawing can look convincing while still hiding a real construction problem.','',NET),
('explanation','Make a physical prototype','Use scrap paper before cutting expensive card. Draw fold lines, label each panel and mark the intended base. Cut only around the outside with adult help when needed. Gently fold along shared edges. Testing a small prototype helps you find errors while changes are still easy.','Plan → fold → inspect → revise',NET),
('explanation','Start from the solid','Imagine a rectangular box two units long, one unit wide and one unit high. It needs two long horizontal faces, two long side faces, and two square end faces. Opposite faces match. Listing the required faces gives us a useful check before we choose an arrangement.','Box dimensions: 2 by 1 by 1',dict(kind='boxnet')),
('explanation','Use matching dimensions','Our box needs four rectangles measuring two units by one unit and two squares measuring one by one. A shared fold edge must have the same length on both panels. Equal numbers of panels do not help if one intended join is longer on one side than the other.','4 rectangles, 2 squares',dict(kind='boxnet')),
('question','Predict a useful placement','Look at the band of four rectangles. The two square end faces must close opposite openings when the band wraps around. Should both squares try to cover the same end? Predict where to place them, then explain which opening each square is meant to close.','',dict(kind='boxnet')),
('answer','Worked example one: a box net','The four rectangles wrap into the four long faces of the box. Attach one square to each side of the band so they close opposite ends. The short edges match the square sides. We have accounted for every face and assigned each panel a different place on the solid.','Close opposite ends with the squares.',dict(kind='boxnet')),
('explanation','Separate folds from cuts','A fold line joins two faces that remain connected in the flat design. A cut separates edges that will meet later when the package closes. Marking these differently helps someone else build your design. A glue tab lies outside a face and supports a join; it does not change the face count.','Shared edge: fold. Outside edge: cut.',NET),
('misconception','Repair an overlapping plan','A two by three rectangle of six squares contains enough square material for a cube, but it does not fold into one correctly. Do not repair it by stretching a face. Keep equal squares and change the connection pattern. The geometry of the intended cube must remain unchanged.','Change the arrangement, not the squares.',BAD),
('explanation','Try a connected cross','Place four equal squares in a straight column. Attach one square on each side of the second square. Check that every square can be reached across a shared whole edge. This connected cross gives the base four immediate neighbours and leaves the final square available as a lid.','A connected six-square cross',NET),
('question','Will moving a panel help?','Compare the invalid rectangle with the cross. Can you explain why moving panels changes the result even though the total number of squares stays six? Predict the role of the last square in the cross. Use face positions rather than saying that one drawing just looks better.','',NET),
('answer','Worked example two: test the repair','Fold the cross mentally or with paper. The base stays still, four neighbouring squares form walls, and the last square closes the top. The repair works because the six panels occupy six different face positions. A successful test explains the change; it is more than a neat final drawing.','Six panels → six distinct face positions',dict(NET,fold=True)),
('explanation','Check the edges that meet','Label an outside edge before folding and find the edge that meets it after folding. Their lengths must match. Repeat around the opening. This catches a wrongly sized lid even when the overall arrangement is sensible. A gap can come from a missing face or from an incorrect dimension.','Meeting edges must have equal lengths.',dict(kind='boxnet')),
('explanation','Record the reason for a revision','A useful design record says what failed, what changed and why the change should help. For example, two panels competed for the same face position, so we moved one to cover the empty top. This explanation lets another designer reproduce and evaluate your repair.','Problem → change → mathematical reason',NET),
('explanation','Packaging is more than appearance','Colouring or rotating the whole net does not fix its fold relationships. Those changes affect the page view, but do not change which faces share edges. A genuine geometric repair changes a dimension or connection responsible for the failure while preserving the intended solid.','Test connections as well as appearance.',NET),
('question','Independent design review','Your partner says a box net is correct because opposite faces have matching dimensions. Is that enough evidence? Think about what else a flat design must do when it folds. Prepare a short checklist a younger designer could use without already knowing the answer.','',dict(kind='boxnet')),
('answer','Use three checks together','Check the required faces, the lengths of meeting edges, and the folded positions. All three matter. A net can have the right shapes and dimensions but still overlap. A prototype that closes correctly, together with a clear explanation, gives much stronger evidence than any single check alone.','Faces • dimensions • folded positions',dict(kind='boxnet'))]),
(4,'Coordinates and Position','Locate and describe points on a first-quadrant grid.',['I can find the origin and axes.','I can read horizontal first.','I can plot points at intersections.'],GRID,[
('opening','A treasure map with a problem','Two explorers read the same pair of numbers and walk to different places. One travels across first; the other goes upward first. How could a map rule stop the disagreement? Today we will build a shared coordinate system so a short pair of numbers names one exact point.','',GRID),
('explanation','Build the grid on paper','Draw horizontal and vertical lines at equal intervals on squared paper. Use a ruler if it helps. The lines meet at intersections. Mark a starting point in the lower left, then number the horizontal and vertical directions from zero. Both sets of numbers need a clear, consistent scale.','Equal intervals; clear scale',dict(kind='grid',points=[])),
('explanation','Find the origin','The point where the two numbered axes meet is the origin. Its coordinates are zero, zero. Zero means no movement from the starting point in that direction. The origin is a real point on the grid, not an empty space between the first two labelled lines.','Origin: (0, 0)',dict(kind='grid',points=[[0,0]],labels=['O'])),
('explanation','Understand an ordered pair','An ordered pair gives the horizontal coordinate first and the vertical coordinate second. We write the pair in brackets with a comma between the numbers. The order matters because each position in the pair has a different job. Today every point stays on this first-quadrant map or its boundary.','Across first, then up',GRID),
('question','Predict the landmark','Our first landmark has coordinates two, three. Start at the origin. Which direction should you travel for the two, and which direction for the three? Imagine tracing the journey with your finger. Keep the destination in mind while we apply the horizontal-first convention.','Locate (2, 3)',dict(kind='grid',points=[[2,3]],labels=['A'],hide=True)),
('answer','Worked example one: plot a point','Travel two units right from the origin, then three units upward. Mark the intersection reached by those movements. The point is two, three. The path helps us locate it, but the ordered pair names the destination, not every step of the path used to arrive there.','A = (2, 3)',GRID),
('explanation','Read a point from the grid','To read the same point, look straight down to find its horizontal coordinate. Then look straight across to find its vertical coordinate. Record those numbers in that order. We can check our reading by plotting the pair again and seeing whether it returns to the original intersection.','Read across, then up.',GRID),
('misconception','Coordinates are not cell names','A coordinate point sits at the crossing of two grid lines. It does not refer to the centre of a square cell. Count intervals between grid lines rather than counting painted squares at random. A clear dot at the intersection removes doubt about the location being described.','Mark the intersection.',GRID),
('explanation','Swap the numbers carefully','Now compare two, three with three, two. The first point is two across and three up. The second is three across and two up. Both numbers appear in both pairs, yet the points differ. Swapping numbers usually changes a location because it changes the job of each number.','(2, 3) and (3, 2) differ.',dict(kind='grid',points=[[2,3],[3,2]],labels=['A','B'])),
('question','Find the second landmark','A flag is five units across and one unit above the horizontal axis. Predict its ordered pair before the label appears. Ask yourself which number should be written first. You can check your choice by describing the journey from the origin aloud.','',dict(kind='grid',points=[[5,1]],labels=['Flag'],hide=True)),
('answer','Worked example two: read and check','The flag is at five, one. Five gives the horizontal position and one gives the vertical position. To check, return to the origin, move five right and one up. The check returns us to the flag, so the words, numbers and drawing agree.','Flag = (5, 1)',dict(kind='grid',points=[[5,1]],labels=['Flag'])),
('explanation','A point on an axis','A point at zero, four needs no horizontal movement and four units upward. It lies on the vertical axis. A point at four, zero lies on the horizontal axis instead. A zero coordinate is useful information, so do not omit it when writing either pair.','A zero coordinate still matters.',dict(kind='grid',points=[[0,4],[4,0]],labels=['C','D'])),
('explanation','Read the scale first','Each gap on our grid represents one unit. On another map, a gap could represent two units or ten metres. Read the labels before interpreting a position. Counting three gaps does not automatically mean the coordinate is three unless the stated scale makes each gap one unit.','Our scale: 1 interval = 1 unit',GRID),
('explanation','Communicate a precise location','A helpful instruction gives a named point and its complete ordered pair. Saying that the treasure is near the top is too vague for another explorer. Saying that it is at two, three lets someone place the same point without seeing your original map.','Name + complete ordered pair',GRID),
('question','Independent coordinate check','A student labels a point four, zero but draws it on the vertical axis above the origin. Decide what went wrong. Which direction does the first number describe, and what does the zero require? Explain the correction rather than merely replacing the dot.','',dict(kind='grid',points=[[4,0]],labels=['E'],hide=True)),
('answer','Use the meaning of zero','The point four, zero belongs four units right along the horizontal axis. Its second coordinate requires no upward movement. The mistake was exchanging the jobs of the two coordinates. Always check both the order and the scale, especially when a point lies on an axis.','(4, 0): four right, zero up',dict(kind='grid',points=[[4,0]],labels=['E']))]),
(5,'Map Routes and Directions','Follow and describe routes using coordinates and direction.',['I can track each route step.','I can update the correct coordinate.','I can check a destination and distance.'],dict(kind='grid',points=[[2,2]],labels=['Start']),[
('opening','Deliveries around a park','A courier must visit a kiosk and then a garden. Knowing the final location is useful, but the courier also needs a route that avoids confusion at every turn. Today we will track positions step by step and distinguish the destination from the distance actually travelled.','',dict(kind='grid',points=[[2,2]],labels=['Start'])),
('explanation','Make a route with a counter','Put a counter at an intersection on squared paper. Move it along grid lines, one interval at a time. Say right, left, up or down as you move. Record a new ordered pair after each part of the journey, instead of waiting until the very end.','Move → record → check',dict(kind='grid',points=[[2,2]],labels=['Start'])),
('explanation','Horizontal movement','A move right increases the first coordinate. A move left decreases it. The second coordinate stays unchanged because the counter has not moved up or down. Point to the row before and after moving. Both positions lie on the same horizontal line of the map.','Right or left changes the first number.',dict(kind='grid',points=[[2,2],[6,2]],labels=['Start','Turn'],path=True)),
('explanation','Vertical movement','A move upward increases the second coordinate. A move downward decreases it. The first coordinate stays unchanged. Check the column containing both points to see why. These rules describe our map directions; a rotated map would need its directions clarified before someone followed your instructions.','Up or down changes the second number.',dict(kind='grid',points=[[6,2],[6,5]],labels=['Turn','Kiosk'],path=True)),
('question','Predict a two-part route','Start at two, two. Move four units right and then three units up. Predict the destination. Keep an intermediate position for the end of the rightward move. That extra record will help you discover which step needs fixing if your answer differs from your partner’s.','Start (2, 2): right 4, up 3',dict(kind='grid',points=[[2,2]],labels=['Start'])),
('answer','Worked example one: find the kiosk','Moving four right changes two, two to six, two. Moving three up then changes six, two to six, five. The kiosk is at six, five. The first part affected only the horizontal coordinate, and the second affected only the vertical coordinate. Each step agrees with the grid.','(2, 2) → (6, 2) → (6, 5)',dict(kind='grid',points=[[2,2],[6,2],[6,5]],labels=['Start','Turn','Kiosk'],path=True)),
('explanation','Continue to another landmark','From the kiosk at six, five, travel two units left. The first coordinate decreases from six to four while the second stays five. The garden is at four, five. Starting this new step from the original starting point would describe a different journey.','(6, 5) → (4, 5)',dict(kind='grid',points=[[6,5],[4,5]],labels=['Kiosk','Garden'],path=True)),
('misconception','Do not reset after each turn','A learner starts every instruction from the origin. That can find several separate points, but it does not follow one continuous route. Each new movement starts where the previous movement ended. Draw connected arrows and keep the most recent ordered pair visible to avoid this mistake.','Continue from the latest position.',dict(kind='grid',points=[[2,2],[6,2],[6,5],[4,5]],labels=['Start','Turn','Kiosk','Garden'],path=True)),
('explanation','Count the route length','The courier travelled four units right, three units up and two units left. Add those distances to obtain nine units travelled. The destination alone does not show that total. Returning partway along a direction still adds distance to the route, even when it reduces the first coordinate.','4 + 3 + 2 = 9 units travelled',dict(kind='grid',points=[[2,2],[6,2],[6,5],[4,5]],labels=['Start','Turn','Kiosk','Garden'],path=True)),
('question','Plan a return route','The courier is at four, five and wants to return to two, two. Predict one route using only horizontal and vertical moves. Decide how much each coordinate must decrease. More than one order of instructions may work, so prepare to justify yours using the actual starting point.','From (4, 5) to (2, 2)',dict(kind='grid',points=[[4,5],[2,2]],labels=['Garden','Home'])),
('answer','Worked example two: return home','Move two units left from four, five to two, five. Then move three units down to two, two. This return route has length five units. Moving down first and left second would also reach home on this unobstructed grid, but the intermediate point would be different.','(4, 5) → (2, 5) → (2, 2)',dict(kind='grid',points=[[4,5],[2,5],[2,2]],labels=['Garden','Turn','Home'],path=True)),
('explanation','Routes and destinations differ','A destination is one location. A route is a sequence of movements leading there. A detour can increase the total distance without changing the destination. When comparing two plans, check both the ordered pairs and the distances rather than assuming every path to the same point is equally long.','Same destination can have different routes.',dict(kind='grid',points=[[2,2],[6,2],[6,5],[4,5]],labels=['Start','Turn','Kiosk','Garden'],path=True)),
('explanation','Stay inside the map','Our first-quadrant map does not show positions left of the vertical axis or below the horizontal axis. Check a planned move before taking it. If it would leave the displayed region, revise the instructions or explain the limitation. Do not silently wrap a counter to the opposite side.','Check map boundaries.',dict(kind='grid',points=[[0,2]],labels=['Boundary'])),
('explanation','Give complete instructions','Tell your partner the starting pair, each direction and distance, and the intended destination. Ask the partner to draw the route without seeing your version. Comparing the two drawings is a useful test of communication. If they differ, identify the first instruction where the paths separate.','Start • direction • distance • destination',dict(kind='grid',points=[[2,2],[6,2],[6,5]],labels=['Start','Turn','Finish'],path=True)),
('question','Independent route detective','A route goes three right and then three left from two, two. A student says nothing happened because the destination is unchanged. Is that a complete description? Decide the destination and total distance separately, and explain what the counter actually did during the journey.','',dict(kind='grid',points=[[2,2]],labels=['Start'])),
('answer','Explain the round trip','The counter returns to two, two, but it travelled six units altogether: three out and three back. Zero change in position does not mean zero distance travelled. Recording the intermediate point five, two makes the movement visible and supports the explanation.','3 + 3 = 6 units; back at (2, 2)',dict(kind='grid',points=[[2,2],[5,2],[2,2]],labels=['Start','Turn','Return'],path=True))]),
]
DATA += [
(6,'Translations','Translate a shape using one shared movement.',['I can describe direction and distance.','I can move every vertex equally.','I can explain what stays the same.'],dict(kind='translate',dx=3,dy=2),[
('opening','A pattern that keeps its shape','A park designer wants to copy a triangular flowerbed farther along a path without turning or resizing it. How can every corner arrive in the right place? Today we will investigate translations: movements that slide a whole shape while keeping its size, shape and orientation.','',dict(kind='translate',dx=3,dy=2)),
('explanation','Slide a paper shape','Cut or trace a triangle on paper and place it on a grid. Mark its starting corners. Slide the triangle gently to a new place without rotating the paper. Compare each original corner with its matching new corner. They should all have travelled the same distance in the same direction.','Same movement for every point',dict(kind='translate',dx=3,dy=2)),
('explanation','Describe the movement precisely','Saying slide it over there is not enough to reproduce a translation. Give a direction and distance for the horizontal move, then for any vertical move. The instruction three right and two up tells a partner exactly how to move every point on our unit grid.','Translate: 3 right, 2 up',dict(kind='translate',dx=3,dy=2)),
('explanation','Choose corresponding vertices','Label the original triangle corners A, B and C. Their images are the matching corners after the translation. Keep the labels paired so that A is compared with its own image, rather than whichever new corner happens to be closest. Matching points give reliable evidence about the movement.','Pair each point with its own image.',dict(kind='translate',dx=3,dy=2)),
('question','Predict the image of A','Vertex A starts at one, one. Translate the shape three units right and two units up. Predict the new coordinates of A. Think about which coordinate changes at each stage. Keep the other corners hidden for a moment so one checked point leads the method.','A starts at (1, 1)',dict(kind='translate',dx=3,dy=2,hide=True)),
('answer','Worked example one: move one point','Three right changes one, one to four, one. Two up then gives four, three. The image of A is four, three. This coordinate calculation records the slide shown on the grid. It does not rotate the point around the origin or exchange the two coordinate positions.','A: (1, 1) → (4, 3)',dict(kind='translate',dx=3,dy=2)),
('explanation','Complete the triangle','B begins at three, one and moves to six, three. C begins at one, three and moves to four, five. Each first coordinate increased by three, and each second coordinate increased by two. Join the image vertices in the same order to obtain the translated triangle.','B → (6, 3); C → (4, 5)',dict(kind='translate',dx=3,dy=2)),
('misconception','Do not move just one corner','If A moves three right but B and C stay still, the triangle changes shape. That is not a translation of the whole triangle. Repair the model by applying the same instruction to every vertex. Then compare the side lengths and corner angles with those of the original triangle.','All vertices follow the same instruction.',dict(kind='translate',dx=3,dy=2)),
('explanation','Check the invariants','An invariant is something that stays the same during a transformation. In a translation, side lengths, angles and orientation stay the same. Position changes. The triangle can point the same way in a new location, so pointing direction alone does not tell us where it has moved.','Same lengths • angles • orientation',dict(kind='translate',dx=3,dy=2)),
('question','Predict a leftward slide','Now start again with A at one, one, B at three, one and C at one, three. Slide every vertex one unit left and two units up. Predict the image of B. Check that the new shape will stay within the displayed first-quadrant grid.','Translate: 1 left, 2 up',dict(kind='translate',dx=-1,dy=2,hide=True)),
('answer','Worked example two: left and up','B moves from three, one to two, three. A moves to zero, three, and C moves to zero, five. Decreasing each first coordinate by one shifts the triangle left. Increasing each second coordinate by two shifts it up. The axis points are valid positions on our grid.','A → (0, 3); B → (2, 3); C → (0, 5)',dict(kind='translate',dx=-1,dy=2)),
('explanation','Reverse a translation','To return the second image to its starting position, slide one unit right and two units down. These reverse movements undo the original changes. Check one pair of coordinates, then check all vertices. A successful reverse operation provides another way to test a translation.','Undo: 1 right, 2 down',dict(kind='translate',dx=-1,dy=2)),
('explanation','Compare two possible images','Two triangles may be the same size and shape without being related by the translation you were given. One might have been turned or reflected. To identify this particular slide, compare corresponding vertices and verify the same horizontal and vertical changes for every pair.','Check every matching pair.',dict(kind='translate',dx=3,dy=2)),
('explanation','Use translations in a design','A repeated motif can be created by translating a single shape by the same step several times. Keep a record of each step so the copies line up predictably. The step controls the spacing; it does not change the size of the original motif.','Repeat a shared slide to make a pattern.',dict(kind='translate',dx=3,dy=2)),
('question','Independent error check','A student claims two points were translated by the same movement. The first moved three right and two up. The second moved three right and one up. Can these both belong to one translated shape? Decide which part of the shared movement rule has failed.','',dict(kind='translate',dx=3,dy=2,hide=True)),
('answer','Explain the shared rule','The vertical changes differ, so the two point movements do not follow one translation. Every point must move by the same horizontal and vertical amounts. Correct the second movement to two up, then check any remaining vertices. Equal changes are stronger evidence than a rough visual resemblance.','Every point: 3 right AND 2 up',dict(kind='translate',dx=3,dy=2))]),
(7,'Reflections','Reflect points and shapes using a mirror line.',['I can locate the mirror line.','I can match equal perpendicular distances.','I can check the reflected shape.'],dict(kind='reflect',axis='x',mirror=5),[
('opening','A sign beside a mirror','A park sign must have a matching design on the opposite side of a mirror line. Sliding a copy across does not always produce the right result. How can we place each matching point exactly? Today we will use the mirror line and equal distances to construct reflections.','',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Fold to explore a reflection','Draw a simple shape on paper, fold the page along a straight line and imagine transferring the marks to the other half. When opened, matching points lie on opposite sides of the fold. The fold gives the mirror line, which controls the position of every reflected point.','The fold acts as a mirror line.',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Identify the mirror line first','Our first mirror is vertical, passing through horizontal coordinate five. We can describe it as the line x equals five. Every point on that line has first coordinate five. The mirror is a whole line, not a single point to rotate around or a boundary that moves with the shape.','Vertical mirror: x = 5',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Measure across the mirror','For a vertical mirror, measure horizontally from the point to the line. That direction is perpendicular to the mirror. Place the image the same distance on the opposite side. The height stays unchanged. Measuring diagonally would give the wrong matching position even if the diagonal lengths happened to agree.','Equal distances, straight across',dict(kind='reflect',axis='x',mirror=5)),
('question','Predict the reflected point','Point A is at two, three. The mirror is the vertical line through five. How many units separate A from the mirror? Predict the image coordinates by placing its partner the same distance on the other side, at the same height. Do not simply swap the coordinate numbers.','A = (2, 3); mirror x = 5',dict(kind='reflect',axis='x',mirror=5,hide=True)),
('answer','Worked example one: vertical mirror','A is three units left of the mirror. Its image must be three units right of the mirror, at eight, three. The two points share the same height. Their joining segment crosses the mirror at a right angle, and the mirror cuts that segment into two equal lengths.','(2, 3) → (8, 3)',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Reflect every triangle corner','Our triangle also has B at four, three and C at two, five. B lies one unit left of the mirror, so its image is six, three. C lies three units left, so its image is eight, five. Join the reflected corners in matching order to complete the image.','B → (6, 3); C → (8, 5)',dict(kind='reflect',axis='x',mirror=5)),
('misconception','A reflection is not a fixed slide','A and B do not travel the same horizontal distance between original and image. A crosses six units, while B crosses two. Their distances depend on how far they start from the mirror. Applying one shared slide would be a translation, and would not produce this reflected triangle.','Use distance from the mirror for each point.',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Points on the mirror stay put','A point on the mirror line is zero units away from it. Its reflected position is therefore the same point. This is a useful check when a shape touches or crosses the mirror. A reflection does not force every point to move to a different location.','On the mirror: zero distance, no change.',dict(kind='reflect',axis='x',mirror=5,points=[[5,2]])),
('question','Predict a horizontal reflection','Now use a horizontal mirror at height four. Point A is at two, one. Predict its image by measuring straight upward to the mirror and the same distance beyond it. Which coordinate should stay unchanged this time, and which one must change?','A = (2, 1); mirror y = 4',dict(kind='reflect',axis='y',mirror=4,points=[[2,1]],hide=True)),
('answer','Worked example two: horizontal mirror','The point is three units below the mirror, so its image is three units above, at two, seven. The first coordinate stays two. The vertical distances to height four are equal. The same distance rule works for either orientation of mirror; only the perpendicular direction changes.','(2, 1) → (2, 7)',dict(kind='reflect',axis='y',mirror=4,points=[[2,1]])),
('explanation','Check lengths and angles','A reflection preserves side lengths and angles, so the image is the same size and shape. Its orientation is reversed, like writing seen in a mirror. Compare matching corners rather than deciding only from the outline. Symmetric shapes can conceal the reversal, making point checks especially useful.','Same lengths and angles; mirrored orientation',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Reflect back to check','Reflect the image across the same mirror a second time. Each point returns to its original location because the same equal distance rule acts in reverse. This provides a practical way to check your construction. If a point does not return, inspect the mirror position and its distance first.','The same reflection twice returns the original.',dict(kind='reflect',axis='x',mirror=5)),
('explanation','Keep the mirror fixed','When comparing the original and image, keep the mirror line in the same place. Moving the line halfway through creates a different transformation. Label the line clearly and draw the matching point pairs. That makes your reasoning visible to someone who did not watch you construct the image.','One fixed mirror for the whole reflection',dict(kind='reflect',axis='x',mirror=5)),
('question','Independent mirror check','A point at four, three reflects in the vertical line through five. A student puts its image at seven, three. Is the new point the correct distance from the mirror? Compare the original and proposed distances before deciding where the image really belongs.','',dict(kind='reflect',axis='x',mirror=5,points=[[4,3]],hide=True)),
('answer','Repair the distance error','The original point is one unit left of the mirror. Seven, three is two units right, so the distances do not match. The correct image is six, three, one unit right. A clear distance check explains exactly why the first proposal failed and why the repair works.','(4, 3) → (6, 3)',dict(kind='reflect',axis='x',mirror=5,points=[[4,3]]))]),
(8,'Rotations and Symmetry','Describe turns and test rotational symmetry.',['I can name the centre and turn.','I can track corresponding points.','I can count matching positions.'],dict(kind='rotate',angle=90),[
('opening','A logo that matches after turning','A designer spins a square logo and notices that it can look unchanged before completing a full turn. Would every rectangle behave the same way? Today we will investigate rotations and rotational symmetry, using a fixed centre and clear turn directions instead of judging a shape only at rest.','',dict(kind='symmetry',shape='square')),
('explanation','Use tracing paper and a pin','Trace a simple shape, mark a centre and hold that point still with a pencil tip. Turn the tracing around the centre without sliding it. Every point follows a circular path around the same fixed position. The original outline remains as a reference for comparing the new position.','Keep one centre fixed.',dict(kind='rotate',angle=90)),
('explanation','Describe a complete rotation','A useful rotation instruction names the centre, the size of the turn and its direction. A quarter turn is ninety degrees, a half turn is one hundred and eighty degrees, and a full turn is three hundred and sixty degrees. Clockwise follows the direction of clock hands.','Centre • angle • direction',dict(kind='rotate',angle=90)),
('explanation','Distance from the centre','During a rotation, each point keeps its own distance from the centre. Different points may have different distances, but every point turns through the same angle. This distinguishes a turn from moving corners independently. Side lengths and angles of the whole shape remain unchanged.','Same distance from the centre',dict(kind='rotate',angle=90)),
('question','Predict a quarter turn','The centre is four, four. Point A is at six, four, directly two units to its right. Predict where A lands after a quarter turn anticlockwise. Imagine the radius turning from pointing right to pointing up, while keeping the same two-unit length.','Centre (4, 4); A = (6, 4)',dict(kind='rotate',angle=90,hide=True)),
('answer','Worked example one: a quarter turn','The radius turns upward, so A lands at four, six. It remains two units from the centre. The centre itself stays at four, four. Turning the whole shape means using that same quarter turn for every corner, rather than treating A as the new centre for the next point.','(6, 4) → (4, 6), anticlockwise',dict(kind='rotate',angle=90)),
('explanation','Clockwise gives another image','Starting again from six, four, a clockwise quarter turn points the radius downward. The image is four, two. Both images are the same distance from the centre, but their positions differ because the turn directions differ. Always include direction when a quarter turn could be interpreted either way.','Clockwise: (6, 4) → (4, 2)',dict(kind='rotate',angle=-90)),
('misconception','Do not turn around the wrong point','A student turns the tracing around one corner after being given the centre of the grid. The new shape may still have the same side lengths, but it is not the requested rotation. Put the pencil back on the named centre and repeat the turn. Location matters as well as angle.','Use the named centre throughout.',dict(kind='rotate',angle=90)),
('explanation','What is rotational symmetry?','A shape has a matching position when turning it around its centre makes it cover its original outline exactly. We count distinct matches during one full turn, including the final full-turn match. Our convention calls a shape with only that final match order one.','Order = matching positions in one full turn',dict(kind='symmetry',shape='square')),
('question','Predict the square matches','Imagine turning an unmarked square around its centre. At which quarter-turn stages will the outline cover the original? Count the matching positions during one full turn, but do not count the starting position as an extra match. Prepare to explain each position rather than guess from the number of sides.','',dict(kind='symmetry',shape='square',hide=True)),
('answer','Worked example two: square symmetry','The square matches after ninety, one hundred and eighty, two hundred and seventy, and three hundred and sixty degrees. That gives rotational symmetry of order four. We count the full-turn match once. Counting both zero degrees and the full turn as separate end positions would incorrectly give five.','Square: 4 matches, order 4',dict(kind='symmetry',shape='square')),
('explanation','Compare a non-square rectangle','A non-square rectangle fails to match after a quarter turn because its long direction has become its short direction. It matches after a half turn and after a full turn. There are two matching positions in one full turn, so its rotational symmetry has order two.','Non-square rectangle: order 2',dict(kind='symmetry',shape='rectangle')),
('explanation','Rotation and reflection differ','A reflection uses a mirror line and reverses orientation. A rotation uses a centre and a turn direction. A shape may have both kinds of symmetry, but a line of reflection is not a centre of rotation. Name the transformation before explaining what stays the same.','Reflection: line. Rotation: centre.',dict(kind='symmetry',shape='rectangle')),
('explanation','Test an asymmetric shape','An ordinary uneven shape may only match after one full turn. Under our convention that is order one. Do not assume every shape has a useful smaller matching turn. Tracing the outline and testing a complete revolution gives evidence, while looking at one corner usually does not.','Only a full-turn match: order 1',dict(kind='symmetry',shape='asymmetric')),
('question','Independent symmetry check','A student says a non-square rectangle has order four because it has four sides. Test that claim with a quarter turn. Will a long horizontal edge cover a short vertical edge? Decide which matching turns are actually supported by the whole outline.','',dict(kind='symmetry',shape='rectangle',hide=True)),
('answer','Use matching outlines as evidence','The rectangle does not match after a quarter turn, so four sides do not prove order four. The half-turn and full-turn positions do match, giving order two. The order is determined by exact covering positions around a centre, not simply by a count of sides or corners.','Non-square rectangle: half turn and full turn',dict(kind='symmetry',shape='rectangle'))]),
]
DATA += [
(9,'Classification Algorithms','Test yes-or-no rules that classify shapes and solids.',['I can choose precise properties.','I can follow a decision path.','I can test and repair a rule.'],dict(kind='classify'),[
('opening','The sorting machine makes a mistake','A museum sorting machine puts every four-sided shape in the square tray. A long rectangle arrives, and the machine makes a mistake. How can we improve its instructions? This extra investigation uses yes-or-no decisions to classify shapes, then tests the rules with examples that challenge our first ideas.','',dict(kind='classify')),
('explanation','Sort a real card collection','Make cards showing squares, non-square rectangles and slanted rhombuses. Turn the cards in different directions without changing their shapes. Ask a partner to sort them using a rule you state aloud. If the rule depends on which way a card faces, it may be describing appearance rather than geometry.','Use properties, not page direction.',dict(kind='classify')),
('explanation','What is an algorithm?','An algorithm is an ordered set of instructions for carrying out a task. Our sorting algorithm asks one clear question at a time. Each answer chooses the next branch. A useful question has a reliable yes-or-no answer based on an observable property, such as the number of sides.','Clear question → yes or no → next step',dict(kind='classify')),
('explanation','Start with the right collection','Before asking whether a shape is square, restrict our collection to four-sided polygons. Curved outlines and triangles need other branches. Knowing the starting collection prevents a rule from making claims about objects it was never designed to handle. Always say what kinds of objects your algorithm is sorting.','Start: four-sided polygons',dict(kind='classify')),
('question','Will equal sides identify a square?','A proposed rule asks only whether all four sides are equal. Predict whether every shape that answers yes must be a square. Compare an ordinary square with a slanted rhombus. Check the corners as well as the side lengths before accepting the rule.','Are all four sides equal?',dict(kind='classify',hide=True)),
('answer','Worked example one: repair the square rule','A non-square rhombus also has four equal sides, so the first test is insufficient. Add another question: are all four angles right angles? Within our quadrilateral collection, four equal sides together with four right angles identify a square. Both conditions are needed.','Equal sides AND four right angles',dict(kind='classify')),
('explanation','Follow the branches','A square answers yes to both questions. A non-square rhombus answers yes to equal sides but no to four right angles. A non-square rectangle answers no to all sides equal, even though its angles are right. Read each branch in order instead of skipping to a familiar name.','Square: yes, yes. Rhombus: yes, no.',dict(kind='classify')),
('misconception','Categories can overlap','A square is also a rectangle because it has four right angles. It is also a rhombus because all four sides are equal. A sorting machine may choose a specific final label, but that does not erase the other true categories. Be careful when a question asks for every category that applies.','Every square is also a rectangle.',dict(kind='classify')),
('explanation','Look for counterexamples','A counterexample is one valid case that shows a proposed always-rule is false. A non-square rectangle disproves the claim that four right angles alone identify a square. One counterexample is enough to reject that claim, even if many squares happened to pass the test correctly.','One counterexample can reject a rule.',dict(kind='classify')),
('question','Do six faces prove a cube?','Now sort solids instead of flat shapes. A proposed rule calls every object with six faces a cube. Predict whether a long rectangular carton would pass this test. What extra property would separate a cube from that carton without relying on colour or the direction of the drawing?','Six faces: is that enough?',dict(kind='solidclass',hide=True)),
('answer','Worked example two: improve the solid rule','The long rectangular prism also has six faces, so the count alone fails. A cube has six square faces and equal edge lengths. Check the face shapes and their connections. The long carton has unequal edge lengths, so it is a counterexample to the original six-face rule.','Cube: 6 square faces, equal edges',dict(kind='solidclass')),
('explanation','Keep dimensions separate','A square is a flat shape, while a cube is a three-dimensional object. Asking whether a solid has four sides confuses different kinds of features. For polygons ask about sides and angles. For solids ask about faces, edges, vertices and curved surfaces, using the relevant mathematical language.','2D: sides and angles. 3D: faces and edges.',dict(kind='solidclass')),
('explanation','Check every possible path','An algorithm needs a next instruction for both yes and no outcomes. A missing branch leaves some objects unsorted. Walk through the diagram with several different cards. Record the question, answer and next location each time so you can discover exactly where a path becomes unclear.','Test both the yes and no branches.',dict(kind='classify')),
('explanation','Revise and test again','When you repair a question, retest examples that previously worked as well as the troublesome counterexample. A new condition might accidentally reject genuine squares. Good improvement keeps valid cases and removes invalid ones. Explain why the revised rule works for the whole stated collection, not just one favourite shape.','Keep valid examples; reject counterexamples.',dict(kind='classify')),
('question','Independent rule review','A learner writes, does it look like a square? Decide why that question is hard for a machine or partner to follow reliably. Replace it with precise yes-or-no tests. Remember a square turned onto one corner is still a square, and categories may share members.','',dict(kind='classify',hide=True)),
('answer','Choose properties you can check','For a four-sided polygon, test whether all four sides are equal and all four angles are right angles. Turning the paper does not change those properties. The revised rule gives evidence for the square label and can be checked with non-square rectangles and rhombuses. That is more reliable than appearance.','Check side lengths AND angles.',dict(kind='classify'))]),
(10,'Integrated Spatial Design','Combine checked nets, routes and transformations in one design.',['I can justify a valid net.','I can communicate a checked route.','I can verify transformations and properties.'],dict(kind='grid',points=[[2,2]],labels=['Depot']),[
('opening','Design a park that really works','A park planner needs a model kiosk, a delivery route and a reflected sign. Each drawing looks attractive, but can the pieces work together? Today we will combine our spatial reasoning skills. We will check each decision with evidence and keep track of the order in which changes happen.','',dict(kind='grid',points=[[2,2]],labels=['Depot'])),
('explanation','Build a planning kit','Use card for the kiosk, squared paper for the map and tracing paper for the sign. Each material helps answer a different question. A card model checks whether panels close. A grid checks location and direction. Tracing helps compare a shape with its translated, reflected or rotated image.','Model • map • tracing',NET),
('explanation','Check the kiosk net','Choose the six-square cross as a cube kiosk model. All six faces are equal squares, each fold joins a whole matching edge, and the panels occupy different positions when closed. A successful paper fold supports the design. A colourful drawing without a fold check would provide weaker evidence.','Faces • edge matches • no overlap',dict(NET,fold=True)),
('explanation','Place landmarks at intersections','The delivery depot starts at two, two on our unit grid. Plot a dot at the intersection rather than in the middle of a cell. Read across first and then up. Giving the planner this starting pair makes the later route reproducible instead of depending on a vague location description.','Depot = (2, 2)',dict(kind='grid',points=[[2,2]],labels=['Depot'])),
('question','Predict the delivery position','The courier moves four units right, three units up and then two units left. Predict the final coordinates. Write an intermediate pair after each instruction so you can check the route piece by piece. Keep the original depot point visible while tracking the latest position.','From (2, 2): right 4, up 3, left 2',dict(kind='grid',points=[[2,2]],labels=['Depot'])),
('answer','Worked example one: a checked route','Four right gives six, two. Three up gives six, five. Two left gives four, five, the kiosk location. The courier travelled nine units in total. The final coordinates describe a position, while the sum of the movement distances describes the route length. Both checks belong in the plan.','(2, 2) → (6, 2) → (6, 5) → (4, 5)',dict(kind='grid',points=[[2,2],[6,2],[6,5],[4,5]],labels=['Depot','Turn','Turn','Kiosk'],path=True)),
('explanation','Translate a garden motif','A separate triangular garden motif must slide three right and two up. Every vertex follows the same movement. For example, one, one becomes four, three. Check the other vertices too. The garden shape keeps its side lengths, angles and orientation, even though its location on the park map changes.','Every vertex: 3 right, 2 up',dict(kind='translate',dx=3,dy=2)),
('misconception','Do not trust a convincing sketch','A sketch can look almost correct while one vertex is a grid unit out of place. Check numerical relationships against the drawing. A net needs matching edges, a route needs correct coordinate changes, and a transformation needs its own invariant rules. Appearance alone cannot establish all three.','Use a mathematical check for each part.',dict(kind='translate',dx=3,dy=2)),
('explanation','Plan an ordered pair of changes','A sign point starts at two, three. First slide it two units right. Then reflect its new position in the vertical mirror through five. These instructions describe a sequence. The input to the reflection is the result of the slide, so keep that intermediate point in the record.','First slide, then reflect.',dict(kind='sequence',stage=0)),
('question','Predict the final sign point','Start at two, three, slide two right, then reflect across the vertical line through five. Predict the final coordinates. Which point is actually being reflected? Measure its distance from the mirror after the slide, rather than measuring from the original point.','',dict(kind='sequence',stage=0)),
('answer','Worked example two: slide then reflect','The slide moves two, three to four, three. That point lies one unit left of the mirror. Its reflection lies one unit right, at six, three. The completed sequence therefore sends the original sign point to six, three. The intermediate pair explains how we obtained the answer.','(2, 3) → (4, 3) → (6, 3)',dict(kind='sequence',stage=2)),
('explanation','Reverse the order to test it','Try reflecting the original two, three first. It becomes eight, three. Sliding that result two right gives ten, three. This differs from six, three, so the two operations cannot simply be exchanged. The example shows why a design must communicate the order of transformations clearly.','Reflect then slide: (8, 3) → (10, 3)',dict(kind='sequence',stage=3)),
('explanation','Classify the kiosk carefully','Our kiosk cube belongs to the rectangular-prism family. Six faces alone would not identify it, because a long carton has six faces too. All six cube faces are squares, and its edges have equal lengths. A classification statement should name the properties supporting the label.','Use properties to justify the object name.',dict(kind='solidclass')),
('explanation','Review the whole plan','A useful review checks each claim separately. Does the kiosk close? Are landmarks at the stated coordinates? Do route steps reach their labelled destinations? Does each transformation follow its named line, centre or movement? Separate checks help locate an error without discarding the parts of the plan that already work.','Check each claim, then combine the evidence.',dict(kind='grid',points=[[2,2],[6,2],[6,5],[4,5]],labels=['Depot','Turn','Turn','Kiosk'],path=True)),
('question','Independent design challenge','Create a small park map with three landmarks, a checked kiosk net and a transformed motif. Ask a partner to reproduce one route and one transformation from your written instructions. What evidence would convince you that your plan is precise, rather than merely attractive?','',dict(kind='grid',points=[[2,2],[6,5],[4,5]],labels=['Depot','Gate','Kiosk'])),
('answer','Explain and improve the design','Compare your partner’s results with your intended map. If something differs, find the first step where the evidence separates. Correct that instruction and test again. Strong spatial reasoning connects models, coordinates and properties, and explains why a result works. It also treats a discovered error as useful information for improvement.','Explain • test • revise • justify',dict(kind='grid',points=[[2,2],[6,5],[4,5]],labels=['Depot','Gate','Kiosk']))]),
]

def build():
 lessons=[]
 for n,title,goal,criteria,model,parts in DATA:
  beats=[scene(*parts[0])]
  beats += [scene('introduction','Today we are learning',
   'Today we are learning to '+goal[0].lower()+goal[1:]+' We will move from objects or hands-on actions to drawings, then connect those drawings with precise mathematical descriptions. Keep paper nearby if you would like to test an idea for yourself. You can pause the player whenever you need more time.',[],model),
   scene('learning_goal','Our learning goal',
   'Our learning goal is to '+goal[0].lower()+goal[1:]+' We want to explain why a result is correct, as well as obtain the result. As you watch, look for the evidence that would help you convince a partner who has not seen your working.',goal,model),
   scene('success_criteria','Three success criteria',
   'Here are our three success criteria. '+ ' '.join(criteria)+' We will check these ideas in two worked examples, investigate a common mistake and finish with an independent challenge. A good explanation links what you see in the model with the mathematical rule being used.',criteria,model)]
  beats += [scene(*p) for p in parts[1:]]
  beats += [scene('recap','Reflect and explain',
   'Return to our learning goal. '+goal+' Choose one example from today and explain the evidence that made its answer convincing. Which of our three success criteria feels secure, and which needs another try? Revisit a model, test your explanation with a partner, and describe one mistake you can now notice and correct.',criteria,model)]
  lessons.append(dict(id=f'space-lesson{n}',number=n,topic='space',section=f'lesson-{n}',title=title,beats=beats,codes=[] if n==9 else ['AC9M5SP01'] if n in [2,3] else ['AC9M5SP02'] if n in [4,5] else ['AC9M5SP01','AC9M5SP02','AC9M5SP03'] if n==10 else ['AC9M5SP03'],enrichment=n==9))
 return lessons
LESSONS=build()
